{
  "flags": [
    {
      "claim": 3,
      "label": "unsupported",
      "evidence": ["clean:story"],
      "evidence_says": "Attrition rate (12 months to 31 Oct 2026): 29.6%; a year earlier (12 months to 31 Oct 2025): 22.8%. The largest month of separations: Jun 2026 with 79.",
      "reason": "The claim states 'Attrition so far in 2026 is 26.2%' and projects an annual rate of 31.4%. The evidence provides only the 12-month attrition rate to 31 Oct 2026 (29.6%) and the prior year (22.8%), with no year-to-date figure for 2026 or a four-year historical comparison to support 'highest in four years'."
    }
  ],
  "gaps": [
    {
      "text": "The claim that low pay is driving attrition needs evidence of causation, not just correlation. The analysis does not show whether Support's high attrition precedes or follows its low pay, or whether other departments with similar pay have different attrition rates.",
      "columns": ["Department", "Annual_Salary", "Termination_Date", "Hire_Date"]
    },
    {
      "text": "To assess whether Support's attrition is disproportionate, the evidence should show attrition rates by department, not just average salary by department. The data shows Support had 62 of 79 separations in Jun 2026, but no department-level attrition rates are provided.",
      "columns": ["Department", "Termination_Date", "Employment_Status"]
    },
    {
      "text": "The claim about 'the highest in four years' requires historical attrition rates for 2023, 2024, and 2025. The evidence provides only the 12-month rates to 31 Oct 2025 (22.8%) and 31 Oct 2026 (29.6%), which is two years, not four.",
      "columns": ["Hire_Date", "Termination_Date", "Employment_Status"]
    }
  ],
  "methodology_concerns": [
    {
      "text": "Annual salary is recorded as base salary without full-time-equivalent adjustment, so departments with more part-time workers (often women) show lower pay than on an FTE basis. Support's mean of $61,677.62 may understate its true compensation relative to other departments.",
      "columns": ["Department", "Annual_Salary", "FTE", "Worker_Type"]
    },
    {
      "text": "The salary analysis uses 1,649 rows (out of 1,770), meaning 121 rows lack salary data. The evidence does not state whether missing salaries are concentrated in any department, which could bias department-level comparisons.",
      "columns": ["Department", "Annual_Salary", "Employment_Status"]
    },
    {
      "text": "The attrition rate is computed as separations ÷ average of month-end headcounts over 12 months. The evidence notes 5 rows have ended status but no end date and 5 dates fall after 31 Oct 2026 (not counted yet), which may understate recent separations.",
      "columns": ["Employment_Status", "Termination_Date"]
    }
  ],
  "next_investigations": [
    {
      "text": "Calculate attrition rate by department (separations ÷ average headcount per department over 12 months) to determine whether Support's attrition is actually higher than other departments, or whether the Jun 2026 spike was an isolated event.",
      "columns": ["Department", "Termination_Date", "Employment_Status", "Hire_Date"]
    },
    {
      "text": "Compare voluntary vs. involuntary attrition by department to identify whether Support's separations are driven by resignations (pay-related) or terminations (performance or restructuring).",
      "columns": ["Department", "Termination_Category", "Termination_Date"]
    },
    {
      "text": "Analyze tenure and job level within Support to see whether attrition is concentrated among junior or senior staff, which would indicate whether pay compression or career progression is the issue.",
      "columns": ["Department", "Job_Level", "Hire_Date", "Termination_Date"]
    }
  ]
}
